/* @autogenerated */
package net.civeira.phylax.feature.observe.access;

import java.util.List;
import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.NotAllowedException;
import net.civeira.phylax.common.security.impl.ActorImpl;

class ObserveAccessUnitTest {

  private static ObserveAccess access(final String scope) {
    return new ObserveAccess("OBSERVABILITY_READER", "OBSERVABILITY_ADMIN", "OBSERVABILITY_ADMIN",
        Optional.ofNullable(scope));
  }

  private static ActorImpl actor(final boolean authenticated, final List<String> roles,
      final List<String> scopes) {
    return ActorImpl.builder().authenticated(authenticated).uid("u").name("observer").tenant("main")
        .roles(roles).groups(List.of()).scopes(scopes).build();
  }

  @Test
  @DisplayName("A reader enters with READ only; an observability admin has every level")
  void levels() {
    ObserveGrant reader = access(null)
        .require(actor(true, List.of("observability_reader"), List.of()), ObserveLevel.READ);
    Assertions.assertEquals("observer", reader.user());
    Assertions.assertFalse(reader.has(ObserveLevel.ADMIN));
    ObserveGrant admin = access(null)
        .require(actor(true, List.of("OBSERVABILITY_ADMIN"), List.of()), ObserveLevel.ADMIN);
    Assertions.assertTrue(admin.has(ObserveLevel.READ));
  }

  @Test
  @DisplayName("Anonymous, without the roles or with the generic admin role: not allowed")
  void denied() {
    ObserveAccess access = access(null);
    Assertions.assertThrows(NotAllowedException.class, () -> access
        .require(actor(false, List.of("OBSERVABILITY_ADMIN"), List.of()), ObserveLevel.READ));
    Assertions.assertThrows(NotAllowedException.class,
        () -> access.require(null, ObserveLevel.READ));
    Assertions.assertThrows(NotAllowedException.class,
        () -> access.require(actor(true, List.of("admin"), List.of()), ObserveLevel.READ));
    Assertions.assertThrows(NotAllowedException.class, () -> access
        .require(actor(true, List.of("OBSERVABILITY_READER"), List.of()), ObserveLevel.ADMIN));
  }

  @Test
  @DisplayName("With a required scope, the role alone is not enough")
  void requiredScope() {
    ObserveAccess access = access("platform:global_access");
    Assertions.assertThrows(NotAllowedException.class, () -> access
        .require(actor(true, List.of("OBSERVABILITY_ADMIN"), List.of()), ObserveLevel.READ));
    Assertions.assertTrue(access
        .require(actor(true, List.of("OBSERVABILITY_ADMIN"), List.of("platform:global_access")),
            ObserveLevel.ADMIN)
        .has(ObserveLevel.ADMIN));
  }
}
